package com.tracepcap.analysis.service;

import static org.assertj.core.api.Assertions.assertThat;

import com.tracepcap.analysis.service.WindowsIdentityResolverService.FolderKind;
import com.tracepcap.analysis.service.WindowsIdentityResolverService.Logon;
import java.io.File;
import java.time.Duration;
import java.util.List;
import org.junit.jupiter.api.Test;

/**
 * {@link WindowsIdentityResolverService#resolveLogons} against a real capture through real tshark
 * (#812). {@code fixtures/windows-logons.pcap} is generated by {@code windows-logons.gen.py} next
 * to it (scapy), so each case is a known packet:
 *
 * <ul>
 *   <li>10.0.0.10: Kerberos logins by alice, then by bob five hours later (twice)
 *   <li>10.0.0.11: carol, plus the machine account DESKTOP-01$ (excluded)
 *   <li>10.0.0.12: LDAP lookups of Clark Collier in the default Users folder (twice), of Dana Lee in
 *       the custom folder Staff/Sales, and of CN=Configuration (infrastructure, never a person)
 *   <li>10.0.0.13: two LDAP lookups in one TCP segment, so two DNs, full of commas, in one field
 *   <li>10.0.0.14: one TCP segment with a KRB-ERROR then grace's AS-REQ. Reading only the first
 *       occurrence of kerberos.msg_type (as before #812) sees "30" and skipped grace.
 * </ul>
 */
class WindowsLogonRealCaptureTest {

  private static final File PCAP =
      new File(WindowsLogonRealCaptureTest.class.getResource("/fixtures/windows-logons.pcap").getFile());

  private final List<Logon> logons = new WindowsIdentityResolverService().resolveLogons(PCAP);

  private List<Logon> on(String ip) {
    return logons.stream().filter(l -> l.ip().equals(ip)).toList();
  }

  @Test
  void twoAccountsOnOneHost_areBothKept_withTheirOwnTimes() {
    List<Logon> host = on("10.0.0.10");

    assertThat(host).extracting(Logon::username).containsExactly("alice", "bob"); // first-seen order
    Logon bob = host.get(1);
    assertThat(bob.seenCount()).isEqualTo(2);
    assertThat(Duration.between(host.get(0).firstSeen(), bob.firstSeen())).isEqualTo(Duration.ofHours(5));
    assertThat(Duration.between(bob.firstSeen(), bob.lastSeen())).isEqualTo(Duration.ofMinutes(1));
  }

  @Test
  void machineAccounts_areExcluded() {
    assertThat(on("10.0.0.11")).extracting(Logon::username).containsExactly("carol");
  }

  @Test
  void ldapLookups_recordTheFolderInPlainWords() {
    List<Logon> host = on("10.0.0.12");

    Logon clark = host.stream().filter(l -> l.username().equals("Clark Collier")).findFirst().orElseThrow();
    assertThat(clark.folderKind()).isEqualTo(FolderKind.USERS);
    assertThat(clark.folder()).isEqualTo("Users");
    assertThat(clark.domain()).isEqualTo("example.com");
    assertThat(clark.directoryEntry()).isEqualTo("CN=Clark Collier,CN=Users,DC=example,DC=com");
    assertThat(clark.seenCount()).isEqualTo(2);
    assertThat(clark.isCandidateOnly()).isFalse();

    Logon dana = host.stream().filter(l -> l.username().equals("Dana Lee")).findFirst().orElseThrow();
    assertThat(dana.folderKind()).isEqualTo(FolderKind.CUSTOM);
    assertThat(dana.folder()).isEqualTo("Staff / Sales"); // outermost first
    assertThat(dana.isCandidateOnly()).isTrue();

    // Infrastructure DNs never become accounts.
    assertThat(host).extracting(Logon::username).doesNotContain("Configuration");
  }

  @Test
  void severalLookupsInOneSegment_areEachRecorded_despiteCommasInTheDn() {
    assertThat(on("10.0.0.13")).extracting(Logon::username).containsExactlyInAnyOrder("Erin Yu", "Frank Ho");
  }

  @Test
  void anAsReqAfterAnotherKerberosMessageInTheSameSegment_isNotSkipped() {
    assertThat(on("10.0.0.14")).extracting(Logon::username).containsExactly("grace");
  }

  @Test
  void theClassificationView_excludesCustomFolderCandidates() {
    var claims = WindowsIdentityResolverService.toClaims(logons);

    assertThat(claims).extracting(WindowsIdentityResolverService.Claim::username)
        .contains("alice", "bob", "carol", "Clark Collier", "grace")
        .doesNotContain("Dana Lee", "DESKTOP-01$");
  }
}
